function chainTriple(start) {
  return Promise.resolve(start)
    .then((x) => x + 1)
    .then((x) => x * 2)
    .then((x) => x - 3);
}

function sumAllPromises(values) {
  return Promise.all(values.map((v) => Promise.resolve(v))).then((nums) =>
    nums.reduce((a, b) => a + b, 0),
  );
}
